#include <print>
#include <cmath>

int main() {
    const double casos[][2] = {{3, 4}, {-5, 2}, {-1, -1}, {0, 0}};
    for (auto [a, b] : casos)
        std::println("|{} + {}| = {} <= {} = |{}| + |{}|",
                     a, b, std::abs(a + b), std::abs(a) + std::abs(b), a, b);
}
